{"__dsh_paper":"ir-container-v1","entries":[{"kind":"SymbolSpec","value":{"symbol_id":"S-p0","scope_ref":"P1","token":"p_0","meaning":"供应商声称的批次次品率标称上限","unit":"dimensionless","role":"VARIABLE","shape":"SCALAR","domain":"PROBABILITY","index_set":[]}},{"kind":"SymbolSpec","value":{"symbol_id":"S-p1-alt","scope_ref":"P1","token":"p_1","meaning":"SPRT 备择的明显超标次品率","unit":"dimensionless","role":"VARIABLE","shape":"SCALAR","domain":"PROBABILITY","index_set":[]}},{"kind":"SymbolSpec","value":{"symbol_id":"S-n","scope_ref":"P1","token":"n","meaning":"抽样检测件数","unit":"件","role":"VARIABLE","shape":"SCALAR","domain":"NONNEGATIVE_INTEGER","index_set":[]}},{"kind":"SymbolSpec","value":{"symbol_id":"S-X","scope_ref":"P1","token":"X","meaning":"n 件中检出的次品数","unit":"件","role":"VARIABLE","shape":"SCALAR","domain":"NONNEGATIVE_INTEGER","index_set":[]}},{"kind":"SymbolSpec","value":{"symbol_id":"S-cR","scope_ref":"P1","token":"c_R","meaning":"拒收阈值（次品数达到或超过即拒收）","unit":"件","role":"VARIABLE","shape":"SCALAR","domain":"NONNEGATIVE_INTEGER","index_set":[]}},{"kind":"SymbolSpec","value":{"symbol_id":"S-cA","scope_ref":"P1","token":"c_A","meaning":"接收阈值（次品数不超过即接收）","unit":"件","role":"VARIABLE","shape":"SCALAR","domain":"NONNEGATIVE_INTEGER","index_set":[]}},{"kind":"SymbolSpec","value":{"symbol_id":"S-alpha","scope_ref":"P1","token":"alpha","meaning":"拒收错误率","unit":"dimensionless","role":"VARIABLE","shape":"SCALAR","domain":"PROBABILITY","index_set":[]}},{"kind":"SymbolSpec","value":{"symbol_id":"S-beta","scope_ref":"P1","token":"beta","meaning":"接收错误率","unit":"dimensionless","role":"VARIABLE","shape":"SCALAR","domain":"PROBABILITY","index_set":[]}},{"kind":"SymbolSpec","value":{"symbol_id":"S-Sn","scope_ref":"P1","token":"S_n","meaning":"累计次品数","unit":"件","role":"VARIABLE","shape":"SCALAR","domain":"NONNEGATIVE_INTEGER","index_set":[]}},{"kind":"SymbolSpec","value":{"symbol_id":"S-Lambda","scope_ref":"P1","token":"***","meaning":"对数似然比","unit":"dimensionless","role":"VARIABLE","shape":"SCALAR","domain":"REAL","index_set":[]}},{"kind":"SymbolSpec","value":{"symbol_id":"S-pi","scope_ref":"P1","token":"pi","meaning":"装配后成品合格率","unit":"dimensionless","role":"VARIABLE","shape":"SCALAR","domain":"PROBABILITY","index_set":[]}},{"kind":"SymbolSpec","value":{"symbol_id":"S-k","scope_ref":"P1","token":"k","meaning":"每次装配尝试的零配件期望成本","unit":"元","role":"VARIABLE","shape":"SCALAR","domain":"NONNEGATIVE_REAL","index_set":[]}},{"kind":"SymbolSpec","value":{"symbol_id":"S-C","scope_ref":"P1","token":"C","meaning":"产出并售出一件合格成品的期望总成本","unit":"元","role":"VARIABLE","shape":"SCALAR","domain":"NONNEGATIVE_REAL","index_set":[]}},{"kind":"SymbolSpec","value":{"symbol_id":"S-V","scope_ref":"P1","token":"V","meaning":"一件退回不合格品的期望处理净收益","unit":"元","role":"VARIABLE","shape":"SCALAR","domain":"REAL","index_set":[]}},{"kind":"SymbolSpec","value":{"symbol_id":"S-d","scope_ref":"P1","token":"d","meaning":"各决策点二元选择（检测/拆解决策向量）","unit":"dimensionless","role":"VARIABLE","shape":"VECTOR","domain":"BOOLEAN","index_set":["d1","d2","d3","d4"]}},{"kind":"SymbolSpec","value":{"symbol_id":"S-case","scope_ref":"P1","token":"case","meaning":"表1情形编号","unit":"dimensionless","role":"VARIABLE","shape":"INDEXED","domain":"INTEGER","index_set":["case1","case2","case3","case4","case5","case6"]}},{"kind":"SymbolSpec","value":{"symbol_id":"S-profit","scope_ref":"P1","token":"Profit","meaning":"每件合格成品的期望利润","unit":"元","role":"VARIABLE","shape":"SCALAR","domain":"REAL","index_set":[]}},{"kind":"SymbolSpec","value":{"symbol_id":"S-pi-j","scope_ref":"P1","token":"pi_j","meaning":"第 j 道工序的半成品合格率","unit":"dimensionless","role":"VARIABLE","shape":"INDEXED","domain":"PROBABILITY","index_set":["j"]}},{"kind":"SymbolSpec","value":{"symbol_id":"S-C-j","scope_ref":"P1","token":"C_j","meaning":"第 j 道工序半成品/成品的期望成本","unit":"元","role":"VARIABLE","shape":"INDEXED","domain":"NONNEGATIVE_REAL","index_set":["j"]}},{"kind":"SymbolSpec","value":{"symbol_id":"S-K-j","scope_ref":"P1","token":"K_j","meaning":"第 j 道工序输入件的期望成本","unit":"元","role":"VARIABLE","shape":"INDEXED","domain":"NONNEGATIVE_REAL","index_set":["j"]}},{"kind":"SymbolSpec","value":{"symbol_id":"S-ptilde","scope_ref":"P1","token":"p_tilde","meaning":"由抽样估计得到的随机次品率","unit":"dimensionless","role":"VARIABLE","shape":"SCALAR","domain":"PROBABILITY","index_set":[]}},{"kind":"AssumptionSpec","value":{"assumption_id":"A-BATCH-LARGE","scope_ref":"P1","statement":"批次量 N 很大（或至少远大于抽样量 n），抽样近似为有放回，检测到的次品数 X ~ Binomial(n, p)。","source_type":"MODELING_CHOICE","justification_refs":["R-OUT"],"risk_level":"LOW","testable":true,"sensitivity_refs":["A-SPRT-OR-FIXED"],"status":"ACTIVE","e1_span":"批次量 $N$ 很大（或至少远大于抽样量 $n$），抽样近似为有放回，检测到的次品数 $X \sim \mathrm{Binomial}(n, p)$。"}},{"kind":"AssumptionSpec","value":{"assumption_id":"A-TEST-EXACT","scope_ref":"P1","statement":"单件检测完全准确，无检测误差（无假阳性/假阴性），检测一件的成本固定。","source_type":"MODELING_CHOICE","justification_refs":["R-OUT"],"risk_level":"LOW","testable":true,"sensitivity_refs":[],"status":"ACTIVE","e1_span":"单件检测完全准确，无检测误差（无假阳性/假阴性），检测一件的成本固定（问题1中未给出具体检测费，故只优化次数，不优化费用；费用优化在问题2中显式出现）。"}},{"kind":"AssumptionSpec","value":{"assumption_id":"A-NO-DESTRUCT","scope_ref":"P1","statement":"检测不破坏零配件，合格件可继续使用。","source_type":"MODELING_CHOICE","justification_refs":["R-OUT"],"risk_level":"LOW","testable":true,"sensitivity_refs":[],"status":"ACTIVE","e1_span":"检测不破坏零配件（否则检测后零件无法进入装配，与题意"检测出的不合格零配件丢弃"矛盾，说明合格件可继续使用）。"}},{"kind":"AssumptionSpec","value":{"assumption_id":"A-SPRT-OR-FIXED","scope_ref":"P1","statement":"允许采用序贯抽样（每次检测一件后立即判断）或固定样本量方案；两者都给出结果。","source_type":"MODELING_CHOICE","justification_refs":["R-OUT"],"risk_level":"MEDIUM","testable":true,"sensitivity_refs":["A-P1-VALUE"],"status":"ACTIVE","e1_span":"允许采用序贯抽样（每次检测一件后立即判断）或固定样本量方案；两者都给出结果，序贯方案在"检测次数少"这一目标上通常更优。"}},{"kind":"AssumptionSpec","value":{"assumption_id":"A-P1-VALUE","scope_ref":"P1","statement":"取 p_1 = 0.20 作为次品率明显超过标称值的备择值。","source_type":"MODELING_CHOICE","justification_refs":["R-OUT"],"risk_level":"HIGH","testable":true,"sensitivity_refs":["A-SPRT-OR-FIXED"],"status":"ACTIVE","e1_span":"取 $p_1 = 0.20$ 作为"次品率明显超过标称值"的备择值（题目未给出，这是必须的假设；$p_1$ 的选择影响平均样本量，可做敏感性分析）。"}},{"kind":"AssumptionSpec","value":{"assumption_id":"A-INDEP","scope_ref":"P1","statement":"各零配件次品独立；成品次品率 p_f 是在两个零配件均合格的条件下装配产生次品的概率。","source_type":"MODELING_CHOICE","justification_refs":["R-OUT"],"risk_level":"MEDIUM","testable":true,"sensitivity_refs":[],"status":"ACTIVE","e1_span":"各零配件次品独立；成品次品率 $p_f$ 是"在两个零配件均合格的条件下"装配产生次品的概率（附录(1)明确）。"}},{"kind":"AssumptionSpec","value":{"assumption_id":"A-NO-TEST-ERROR","scope_ref":"P1","statement":"检测准确无误，检测出的不合格件直接丢弃，不产生额外成本（除检测费本身）。","source_type":"MODELING_CHOICE","justification_refs":["R-OUT"],"risk_level":"LOW","testable":true,"sensitivity_refs":[],"status":"ACTIVE","e1_span":"检测准确无误（与问题1一致），检测出的不合格件直接丢弃，不产生额外成本（除检测费本身）。"}},{"kind":"AssumptionSpec","value":{"assumption_id":"A-DISASSEMBLE-PERFECT","scope_ref":"P1","statement":"拆解不损坏零配件，拆解后的零配件可重新进入装配；拆解费用按件计。","source_type":"MODELING_CHOICE","justification_refs":["R-OUT"],"risk_level":"MEDIUM","testable":true,"sensitivity_refs":[],"status":"ACTIVE","e1_span":"拆解不损坏零配件，拆解后的零配件可重新进入装配；拆解费用按件计。"}},{"kind":"AssumptionSpec","value":{"assumption_id":"A-REPEAT-INFINITE","scope_ref":"P1","statement":"拆解回流与用户退货回流可以无限次重复；用户退回的不合格品同样可拆解。","source_type":"MODELING_CHOICE","justification_refs":["R-OUT"],"risk_level":"MEDIUM","testable":true,"sensitivity_refs":[],"status":"ACTIVE","e1_span":"拆解回流与用户退货回流可以无限次重复（实际收敛很快，因为每次回流合格率提升）；用户退回的不合格品同样可拆解。"}},{"kind":"AssumptionSpec","value":{"assumption_id":"A-DEMAND-GIVEN","scope_ref":"P1","statement":"市场需求充足，每件合格成品都能按市场售价售出；不合格品被用户退回的概率为 1。","source_type":"MODELING_CHOICE","justification_refs":["R-OUT"],"risk_level":"MEDIUM","testable":true,"sensitivity_refs":[],"status":"ACTIVE","e1_span":"市场需求充足（畅销产品），每件合格成品都能按市场售价售出；不合格品被用户退回的概率为 1（无条件调换）。"}},{"kind":"AssumptionSpec","value":{"assumption_id":"A-UNIT-PROFIT","scope_ref":"P1","statement":"以每件成品进入市场后的期望净利润为目标，等价地用单件期望总成本比较。","source_type":"MODELING_CHOICE","justification_refs":["R-OUT"],"risk_level":"MEDIUM","testable":true,"sensitivity_refs":[],"status":"ACTIVE","e1_span":"以"每售出一件合格成品"或"每件成品流向市场"为核算单位。两种核算方式会给出不同数字，需统一。"}},{"kind":"AssumptionSpec","value":{"assumption_id":"A-NETWORK-STRUCTURE","scope_ref":"P1","statement":"图1结构为：零配件1-4经工序1产出半成品1-3，半成品1-3与零配件5-8经工序2装配成成品；图缺失，结构需假设。","source_type":"MODELING_CHOICE","justification_refs":["R-OUT"],"risk_level":"HIGH","testable":true,"sensitivity_refs":["A-STRUCTURE-GUESS"],"status":"ACTIVE","e1_span":"图 1 的结构为：零配件 1–4 → 工序 1 → 半成品 1、2、3（表2列出半成品1、2、3，次品率均 10%，装配成本 8，检测成本 4，拆解费用 6）；零配件 5–8 → 工序 2 → 半成品（表2只列了半成品1、2、3，共3个半成品，但8个零配件）。"}},{"kind":"AssumptionSpec","value":{"assumption_id":"A-STRUCTURE-GUESS","scope_ref":"P1","statement":"采用表2给出的层级：零配件1-4经工序1产出半成品1-3，半成品1-3与零配件5-8经工序2装配成成品。","source_type":"MODELING_CHOICE","justification_refs":["R-OUT"],"risk_level":"HIGH","testable":true,"sensitivity_refs":["A-NETWORK-STRUCTURE"],"status":"ACTIVE","e1_span":"工序1：零配件1、2、3、4 组装成半成品1、2、3（半成品1由零配件1、半成品2由零配件2、半成品3由零配件3和4，或类似）；工序2：半成品1、2、3 + 零配件5、6、7、8 装配成成品。"}},{"kind":"AssumptionSpec","value":{"assumption_id":"A-PRIOR","scope_ref":"P1","statement":"取弱信息先验 Beta(1,1)（均匀），或基于供应商标称值取 Beta(1,9)；后验 Beta(1+x, 1+n-x)。","source_type":"MODELING_CHOICE","justification_refs":["R-OUT"],"risk_level":"MEDIUM","testable":true,"sensitivity_refs":[],"status":"ACTIVE","e1_span":"取弱信息先验 $\mathrm{Beta}(1,1)$（均匀），或基于供应商标称值取 $\mathrm{Beta}(1,9)$（先验均值 10%）。后验 $\mathrm{Beta}(1+x, 1+n-x)$。"}},{"kind":"AssumptionSpec","value":{"assumption_id":"A-SAMPLING-COST","scope_ref":"P1","statement":"抽样检测费用计入总成本，需在抽样成本与决策改进收益之间权衡。","source_type":"MODELING_CHOICE","justification_refs":["R-OUT"],"risk_level":"MEDIUM","testable":true,"sensitivity_refs":[],"status":"ACTIVE","e1_span":"抽样检测费用计入总成本（问题1中企业自付）。需在"抽样成本"与"决策改进收益"之间权衡：样本量越大，后验越集中，决策越准，但检测费越高。"}},{"kind":"AssumptionSpec","value":{"assumption_id":"A-POSTERIOR-MEAN-DECISION","scope_ref":"P1","statement":"重做问题2/3时采用后验均值代入问题2/3的利润公式。","source_type":"MODELING_CHOICE","justification_refs":["R-OUT"],"risk_level":"MEDIUM","testable":true,"sensitivity_refs":["A-PRIOR"],"status":"ACTIVE","e1_span":"在重做问题2/3时，采用后验均值 $\bar p = \mathbb{E}[\tilde p]$ 代入问题2/3的利润公式（等价于贝叶斯决策，因为利润是 $p$ 的线性/有理函数时后验期望可解析；若非线性则用数值积分）。"}},{"kind":"EquationSpec","value":{"equation_id":"E-reject-tail","scope_ref":"P1","expression":"Pr[Bin(n, p_0) >= c_R] <= alpha","representation":"SYMPY","lhs_symbols":["S-cR"],"rhs_symbols":["S-n","S-p0","S-alpha"],"equation_type":"CONSTRAINT","unit":"dimensionless","depends_on":["E-binom-pmf"],"source":"情形(1)需95%信度认定p>p_0：找阈值c_1使 Pr[Bin(n,p_0) >= c_1] <= 0.05"}},{"kind":"EquationSpec","value":{"equation_id":"E-accept-tail","scope_ref":"P1","expression":"Pr[Bin(n, p_0) <= c_A] >= 1 - beta","representation":"SYMPY","lhs_symbols":["S-cA"],"rhs_symbols":["S-n","S-p0","S-beta"],"equation_type":"CONSTRAINT","unit":"dimensionless","depends_on":["E-binom-pmf"],"source":"情形(2)需90%信度认定p<=p_0：要求 Pr[Bin(n,p_0) <= c_2] >= 0.90"}},{"kind":"EquationSpec","value":{"equation_id":"E-binom-pmf","scope_ref":"P1","expression":"Pr[X = x] = C(n, x) * p**x * (1-p)**(n-x)","representation":"SYMPY","lhs_symbols":["S-X"],"rhs_symbols":["S-n"],"equation_type":"DEFINITION","unit":"dimensionless","depends_on":[],"source":"检测到的次品数 X ~ Binomial(n, p)"}},{"kind":"EquationSpec","value":{"equation_id":"E-llr","scope_ref":"P1","expression":"Lambda_n = S_n * log(p_1*(1-p_0)/(p_0*(1-p_1))) + n * log((1-p_1)/(1-p_0))","representation":"SYMPY","lhs_symbols":["S-Lambda","S-Sn"],"rhs_symbols":["S-n","S-p0","S-p1-alt"],"equation_type":"DEFINITION","unit":"dimensionless","depends_on":[],"source":"SPRT 每检测一件后计算似然比，取对数后判决规则化为对 log 似然比 Lambda_n 的比较"}},{"kind":"EquationSpec","value":{"equation_id":"E-sprt-bounds","scope_ref":"P1","expression":"A = (1-beta)/alpha ; B = beta/(1-alpha)","representation":"SYMPY","lhs_symbols":["S-alpha","S-beta"],"rhs_symbols":[],"equation_type":"DEFINITION","unit":"dimensionless","depends_on":[],"source":"判决边界（alpha=0.05 拒收错误率，beta=0.10 接收错误率）"}},{"kind":"EquationSpec","value":{"equation_id":"E-pi","scope_ref":"P1","expression":"pi = (1 - p1_eff) * (1 - p2_eff) * (1 - p_f)","representation":"SYMPY","lhs_symbols":["S-pi"],"rhs_symbols":[],"equation_type":"DEFINITION","unit":"dimensionless","depends_on":[],"source":"装配后成品合格率 pi = (1-p1_eff)(1-p2_eff)(1-p_f)"}},{"kind":"EquationSpec","value":{"equation_id":"E-k","scope_ref":"P1","expression":"k = sum_i ( (c_i + t_i) / (1 - p_i) if test_i else c_i )","representation":"SYMPY","lhs_symbols":["S-k"],"rhs_symbols":[],"equation_type":"DEFINITION","unit":"元","depends_on":[],"source":"定义每次装配尝试的零配件期望成本 k"}},{"kind":"EquationSpec","value":{"equation_id":"E-C-disassemble","scope_ref":"P1","expression":"C = k + (a + t_f + (1 - pi) * r) / pi","representation":"SYMPY","lhs_symbols":["S-C"],"rhs_symbols":["S-k","S-pi"],"equation_type":"DEFINITION","unit":"元","depends_on":["E-pi","E-k"],"source":"C = k + (a + t_f + (1-pi) r)/pi （拆解）"}},{"kind":"EquationSpec","value":{"equation_id":"E-C-no-disassemble","scope_ref":"P1","expression":"C = (k + a + t_f) / pi","representation":"SYMPY","lhs_symbols":["S-C"],"rhs_symbols":["S-k","S-pi"],"equation_type":"DEFINITION","unit":"元","depends_on":["E-pi","E-k"],"source":"C = (k+a+t_f)/pi （不拆解）"}},{"kind":"EquationSpec","value":{"equation_id":"E-profit","scope_ref":"P1","expression":"Profit = s - C","representation":"SYMPY","lhs_symbols":["S-profit"],"rhs_symbols":["S-C"],"equation_type":"OBJECTIVE","unit":"元","depends_on":["E-C-disassemble","E-C-no-disassemble"],"source":"每件合格品利润 = s - C"}},{"kind":"EquationSpec","value":{"equation_id":"E-V","scope_ref":"P1","expression":"V = -r - a + (s*pi - L*(1-pi)) - (1-pi) * V","representation":"SYMPY","lhs_symbols":["S-V"],"rhs_symbols":["S-pi"],"equation_type":"DEFINITION","unit":"元","depends_on":["E-pi"],"source":"设单件退回品净价值 V：V = -5 - 6 + 39.20 - 0.271*(再退回的损失 + V)"}},{"kind":"EquationSpec","value":{"equation_id":"E-C-j","scope_ref":"P1","expression":"C_j = K_j + (a_j + t_j * 1_{d_j} + (1 - pi_j) * r_j * 1_{disa